struct Packet { uint32_t magic; uint32_t sequence; int32_t temperatureCenti; };
static_assert(sizeof(Packet) == 12, "Format paket harus 12 byte");
QueueHandle_t inbox;
bool ready = false;
// Arduino-ESP32 3.x; jangan gunakan signature callback core 2.x.
void received(const esp_now_recv_info_t* info, const uint8_t* data, int length) {
  if (length != sizeof(Packet)) return;
  Packet packet;
  memcpy(&packet, data, sizeof(packet));
  if (packet.magic != 0x494F5431 || packet.temperatureCenti < -4000 || packet.temperatureCenti > 12500) return;
  // Callback Wi-Fi harus singkat. Proses dan cetak di loop.
  xQueueSend(inbox, &packet, 0); // Jika penuh, sampel demo dilewati.
}
void setup() {
  Serial.begin(115200);
  inbox = xQueueCreate(4, sizeof(Packet));
  if (!inbox) { Serial.println("Antrean gagal"); return; }
  WiFi.mode(WIFI_STA);
  Serial.print("MAC penerima: "); Serial.println(WiFi.macAddress());
  if (esp_wifi_set_channel(6, WIFI_SECOND_CHAN_NONE) != ESP_OK ||
      esp_now_init() != ESP_OK || esp_now_register_recv_cb(received) != ESP_OK) {
    Serial.println("Inisialisasi gagal"); return;
  }
  ready = true;
}
void loop() {
  if (!ready) return;
  Packet packet;
  if (xQueueReceive(inbox, &packet, 0) == pdTRUE) {
    Serial.print("Sequence="); Serial.print(packet.sequence);
    Serial.print(" suhu SIMULASI="); Serial.println(packet.temperatureCenti / 100.0f);
  }
}

#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

struct Packet { uint32_t magic; uint32_t sequence; int32_t temperatureCenti; };
static_assert(sizeof(Packet) == 12, "Format paket harus 12 byte");
// Ganti keenam byte dengan MAC STA penerima, misalnya AA:BB:CC:DD:EE:FF.
uint8_t receiverMac[6] = {0, 0, 0, 0, 0, 0};
uint32_t sequence = 0;
unsigned long lastSend = 0;
bool ready = false;
void setup() {
  Serial.begin(115200); WiFi.mode(WIFI_STA);
  bool empty = true;
  for (uint8_t value : receiverMac) if (value != 0) empty = false;
  if (empty) { Serial.println("Isi MAC penerima terlebih dahulu"); return; }
  if (esp_wifi_set_channel(6, WIFI_SECOND_CHAN_NONE) != ESP_OK || esp_now_init() != ESP_OK) return;
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, receiverMac, 6);
  peer.channel = 6; peer.ifidx = WIFI_IF_STA; peer.encrypt = false;
  ready = esp_now_add_peer(&peer) == ESP_OK;
}
void loop() {
  if (!ready || millis() - lastSend < 2000UL) return;
  lastSend = millis();
  Packet packet = {0x494F5431, ++sequence, 2940};
  esp_err_t result = esp_now_send(receiverMac, reinterpret_cast<uint8_t*>(&packet), sizeof(packet));
  Serial.println(result == ESP_OK ? "Masuk antrean kirim; periksa penerima" : "Gagal mengantrekan kiriman");
}

#include <BLEDevice.h>
