const char* SERVICE_UUID = "7d930001-2e91-4d88-8c27-08f3ae99c001";
const char* VALUE_UUID = "7d930002-2e91-4d88-8c27-08f3ae99c001";
std::atomic<bool> advertiseAgain(false);
class Events : public BLEServerCallbacks {
  void onDisconnect(BLEServer* server) override { advertiseAgain.store(true); }
};
Events events;
void setup() {
  Serial.begin(115200);
  BLEDevice::init("FIKS-Lab-BLE");
  BLEServer* server = BLEDevice::createServer();
  server->setCallbacks(&events);
  BLEService* service = server->createService(SERVICE_UUID);
  BLECharacteristic* value = service->createCharacteristic(VALUE_UUID, BLECharacteristic::PROPERTY_READ);
  value->setValue("29.4"); // ASCII simulasi; bukan sensor asli dan bukan format standar Bluetooth suhu.
  service->start();
  BLEAdvertising* advertising = BLEDevice::getAdvertising();
  advertising->addServiceUUID(SERVICE_UUID);
  advertising->setScanResponse(true);
  BLEDevice::startAdvertising();
  Serial.println("Buka scanner BLE, connect, cari service dan Read characteristic");
}
void loop() {
  if (advertiseAgain.exchange(false)) BLEDevice::startAdvertising();
  delay(20);
}

function decodeUplink(input) {
  const b = input.bytes;
  if (input.fPort !== 2 || !Array.isArray(b) || b.length !== 4 ||
      b.some(value => !Number.isInteger(value) || value < 0 || value > 255)) {
    return {errors: ["Butuh FPort 2 dan tepat empat byte"]};
  }
  if (b[0] !== 1 || (b[3] & 0xFC) !== 0) return {errors: ["Versi atau flag tidak dikenal"]};
  let raw = (b[1] << 8) | b[2];
  if (raw & 0x8000) raw -= 65536;
  const temperature = raw / 100;
  if (temperature < -40 || temperature > 125) return {errors: ["Suhu di luar rentang latihan"]};
  return {data: {temperature, unit: "C", doorOpen: Boolean(b[3] & 1),
    waterDetected: Boolean(b[3] & 2)}, warnings: []};
}
