#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>
#include <esp_system.h>
#include <cstring>

// Ganti dengan password unik 8-63 karakter untuk AP latihan ini.
const char* AP_PASSWORD = "GANTI_PASSWORD_AP_UNIK";
const int SETUP_BUTTON = 27; // Tombol ke GND, tahan ketika boot.
struct Config { uint32_t magic; char ssid[33]; char password[64]; char broker[254]; };
Config config = {};
WebServer server(80);
Preferences store;
String token;
bool setupMode = false, saved = false;
unsigned long openedAt = 0, savedAt = 0;

bool validHost(const String& host) {
  if (host.length() == 0 || host.length() > 253) return false;
  for (unsigned int i = 0; i < host.length(); i++) {
    char c = host[i];
    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
          (c >= '0' && c <= '9') || c == '.' || c == '-')) return false;
  }
  return true; // Pemeriksaan bentuk dasar, bukan jaminan DNS/host dapat dijangkau.
}
void setup() {
  Serial.begin(115200); pinMode(SETUP_BUTTON, INPUT_PULLUP); delay(50);
  if (!store.begin("iot-wifi", false)) { Serial.println("NVS gagal"); return; }
  bool stored = store.getBytesLength("config") == sizeof(config);
  if (stored) store.getBytes("config", &config, sizeof(config));
  stored = stored && config.magic == 0x494F5432 &&
    memchr(config.ssid, 0, sizeof(config.ssid)) &&
    memchr(config.password, 0, sizeof(config.password)) &&
    memchr(config.broker, 0, sizeof(config.broker));
  setupMode = !stored || digitalRead(SETUP_BUTTON) == LOW;
  if (!setupMode) {
    WiFi.mode(WIFI_STA); WiFi.begin(config.ssid, config.password);
    Serial.println("Mencoba konfigurasi tersimpan. Pantau status Wi-Fi di loop.");
    Serial.print("Host broker tersimpan: "); Serial.println(config.broker);
    store.end(); return;
  }
  if (String(AP_PASSWORD).startsWith("GANTI_") || strlen(AP_PASSWORD) < 8 || strlen(AP_PASSWORD) > 63) {
    Serial.println("Ubah AP_PASSWORD unik dahulu lalu upload ulang"); store.end(); setupMode = false; return;
  }
  WiFi.mode(WIFI_AP);
  if (!WiFi.softAP("FIKS-Setup-Lab", AP_PASSWORD)) { store.end(); setupMode = false; return; }
  token = String(esp_random(), HEX) + String(esp_random(), HEX);
  server.on("/", HTTP_GET, []() {
    String form = "<!doctype html><html lang='id'><meta name='viewport' content='width=device-width,initial-scale=1'>"
      "<title>Setup lab</title><h1>Konfigurasi Wi-Fi</h1><form method='POST' action='/save'>"
      "<label>SSID <input name='ssid' maxlength='32' required></label><br>"
      "<label>Password Wi-Fi <input name='password' type='password' minlength='8' maxlength='63' required></label><br>"
      "<label>Host broker, tanpa port/path <input name='broker' maxlength='253' required></label>"
      "<input type='hidden' name='token' value='" + token + "'><br><button>Simpan dan restart</button></form>"
      "<p>Hanya untuk AP lab pribadi. Halaman menutup setelah lima menit.</p></html>";
    server.sendHeader("Cache-Control", "no-store");
    server.send(200, "text/html; charset=utf-8", form);
  });
  server.on("/save", HTTP_POST, []() {
    if (saved) { server.send(409, "text/plain", "Sedang restart"); return; }
    if (server.arg("token") != token) { server.send(403, "text/plain", "Token tidak cocok"); return; }
    String ssid = server.arg("ssid"), password = server.arg("password"), broker = server.arg("broker");
    if (ssid.length() == 0 || ssid.length() > 32 || password.length() < 8 || password.length() > 63 || !validHost(broker)) {
      server.send(400, "text/plain", "Periksa panjang isian dan host broker"); return;
    }
    Config next = {}; next.magic = 0x494F5432;
    ssid.toCharArray(next.ssid, sizeof(next.ssid));
    password.toCharArray(next.password, sizeof(next.password));
    broker.toCharArray(next.broker, sizeof(next.broker));
    if (store.putBytes("config", &next, sizeof(next)) != sizeof(next)) {
      server.send(500, "text/plain", "Simpan gagal"); return;
    }
    server.sendHeader("Cache-Control", "no-store");
    server.send(200, "text/plain", "Tersimpan, perangkat akan restart. Periksa koneksi pada Serial.");
    saved = true; savedAt = millis();
  });
  server.begin(); openedAt = millis();
  Serial.print("Hubungkan ke AP lab lalu buka http://"); Serial.println(WiFi.softAPIP());
}
void loop() {
  if (setupMode) {
    server.handleClient();
    if (saved && millis() - savedAt >= 700UL) { store.end(); ESP.restart(); }
    if (millis() - openedAt >= 300000UL) {
      server.stop(); WiFi.softAPdisconnect(true); store.end(); setupMode = false;
      Serial.println("Setup ditutup. Restart dengan tombol ditekan untuk membuka lagi.");
    }
    return;
  }
  static unsigned long last = 0;
  if (millis() - last >= 5000UL) {
    last = millis(); Serial.println(WiFi.status() == WL_CONNECTED ? "Wi-Fi terhubung" : "Wi-Fi belum terhubung");
  }
}

#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>
#include <math.h>

const int TEMP_PIN = 4, DOOR_PIN = 27, LEAK_TEST_PIN = 26;
const char* TELEMETRY = "lab/esp32-noc-01/telemetry";
const char* STATUS = "lab/esp32-noc-01/status";
DHT sensor(TEMP_PIN, DHT22);
WiFiClient network; // Hanya LAN lab. Untuk internet, terapkan TLS.
PubSubClient mqtt(network);
unsigned long lastSample = 0, lastWifi = 0, lastMqtt = 0;
void setup() {
  Serial.begin(115200); sensor.begin();
  pinMode(DOOR_PIN, INPUT_PULLUP); pinMode(LEAK_TEST_PIN, INPUT_PULLUP);
  WiFi.mode(WIFI_STA); WiFi.begin("GANTI_SSID_2_4_GHZ", "GANTI_PASSWORD_WIFI");
  mqtt.setServer("192.168.1.10", 1883); mqtt.setBufferSize(512);
  mqtt.setKeepAlive(30); mqtt.setSocketTimeout(2);
}
void loop() {
  unsigned long now = millis();
  if (WiFi.status() != WL_CONNECTED && now - lastWifi >= 10000UL) {
    lastWifi = now; WiFi.reconnect();
  }
  if (WiFi.status() == WL_CONNECTED && !mqtt.connected() && now - lastMqtt >= 5000UL) {
    lastMqtt = now;
    // Last Will offline disetel sebelum connect. Status online setelah login sukses.
    if (mqtt.connect("noc-monitor-01", "noc-device", "GANTI_PASSWORD_NOC_DEVICE", STATUS, 1, true, "offline")) {
      mqtt.publish(STATUS, "online", true);
    }
  }
  if (mqtt.connected()) mqtt.loop();
  if (now - lastSample < 5000UL) return;
  lastSample = now;
  float temperature = sensor.readTemperature();
  bool valid = isfinite(temperature) && temperature >= -40 && temperature <= 80;
  bool doorOpen = digitalRead(DOOR_PIN) == HIGH;
  bool waterDetected = digitalRead(LEAK_TEST_PIN) == LOW;
  char temperatureText[20], payload[384];
  if (valid) snprintf(temperatureText, sizeof(temperatureText), "%.1f", temperature);
  else snprintf(temperatureText, sizeof(temperatureText), "null");
  snprintf(payload, sizeof(payload),
    "{\"deviceId\":\"esp32-noc-01\",\"temperature\":%s,\"unit\":\"C\",\"temperatureValid\":%s,"
    "\"doorOpen\":%s,\"waterDetected\":%s,\"simulated\":true,\"uptimeMs\":%lu}",
    temperatureText, valid ? "true" : "false", doorOpen ? "true" : "false",
    waterDetected ? "true" : "false", now);
  Serial.println(payload);
  if (mqtt.connected()) mqtt.publish(TELEMETRY, payload, false);
  // Belum ada penyimpanan offline. Sampling status pintu bukan pencatat semua kejadian buka/tutup.
}

import math

def assess(packet, received_at_ms, now_ms):
    if not isinstance(packet, dict) or packet.get("deviceId") != "esp32-noc-01" or packet.get("unit") != "C":
        raise ValueError("Identitas/format salah")
    for field in ("temperatureValid", "doorOpen", "waterDetected", "simulated"):
        if type(packet.get(field)) is not bool:
            raise ValueError("Flag harus boolean")
    temperature = packet.get("temperature")
    if packet["temperatureValid"]:
        if type(temperature) not in (int, float) or not math.isfinite(temperature) or not -40 <= temperature <= 80:
            raise ValueError("Suhu valid harus angka pada rentang latihan")
    elif temperature is not None:
        raise ValueError("Suhu gagal harus null")
    if type(received_at_ms) is not int or type(now_ms) is not int:
        raise ValueError("Waktu pengamat harus integer milidetik")
    if received_at_ms > now_ms + 5000:
        return ["JAM_PENGAMAT_PERLU_DIPERIKSA"]
    if now_ms - received_at_ms > 20000:
        return ["DATA_LAMA"]
    alarms = []
    if not packet["temperatureValid"]:
        alarms.append("SENSOR_SUHU_GAGAL")
    elif temperature >= 30:
        alarms.append("SUHU_TINGGI")
    if packet["doorOpen"]:
        alarms.append("PINTU_TERBUKA")
    if packet["waterDetected"]:
        alarms.append("DETEKSI_AIR")
    return alarms or ["NORMAL"]

